#!/usr/bin/env bash
# Prints the Homebrew formula for a release.
# Usage: homebrew-formula.sh VERSION MACOS_SHA256 LINUX_SHA256
set -euo pipefail

version="$1"
macos_sha="$2"
linux_sha="$3"
base="https://github.com/vangheem/gitsnack/releases/download/v${version}"

cat <<EOF
# Generated by vangheem/gitsnack's release workflow; edits here are overwritten.
class Gitsnack < Formula
  desc "Native GitHub pull request review app with opencode agent sessions"
  homepage "https://github.com/vangheem/gitsnack"
  version "${version}"
  license "MIT"

  on_macos do
    url "${base}/gitsnack-macos-universal.tar.gz"
    sha256 "${macos_sha}"
  end

  on_linux do
    on_intel do
      url "${base}/gitsnack-linux-x86_64.tar.gz"
      sha256 "${linux_sha}"
    end
  end

  depends_on "gh"

  def install
    bin.install "gitsnack"
  end

  def caveats
    <<~EOS
      gitsnack uses the GitHub CLI; log in with \`gh auth login\` if you haven't.
      The agent panel needs opencode v2: https://opencode.ai
    EOS
  end

  test do
    assert_match "demo", shell_output("#{bin}/gitsnack --list-scenes")
  end
end
EOF
